"""The Card Studio golden fixtures are generated by the real code: the checked-in files must equal what
scripts/export_studio_fixtures.py produces. The TS twin tests read the same files. Regenerate with that script."""
import importlib.util
import json
from pathlib import Path

REPO = Path(__file__).resolve().parents[4]
FIXTURES = REPO / "backend" / "apps" / "card_designs" / "fixtures"


def _script():
    spec = importlib.util.spec_from_file_location("export_studio_fixtures", REPO / "scripts" / "export_studio_fixtures.py")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def _dump(data):
    return json.dumps(data, indent=1, sort_keys=True) + "\n"


def test_plan_fixture_matches_the_server_code():
    assert (FIXTURES / "studio_plan_cases.json").read_text(encoding="utf-8") == _dump(_script().plan_cases()), \
        "run: python scripts/export_studio_fixtures.py"


def test_compat_fixture_matches_the_server_code():
    assert (FIXTURES / "studio_compat_cases.json").read_text(encoding="utf-8") == _dump(_script().compat_cases()), \
        "run: python scripts/export_studio_fixtures.py"


def test_the_plan_fixture_covers_every_case_kind():
    kinds = {case["kind"] for case in json.loads((FIXTURES / "studio_plan_cases.json").read_text(encoding="utf-8"))["cases"]}
    assert kinds == {"place", "gradient", "rich_plan"}
